{
  "sql": "SELECT COUNT(*) AS missed_visits FROM visits WHERE actual_date IS NULL AND planned_date BETWEEN DATE('now') - INTERVAL '1 month' AND DATE('now') - INTERVAL '1 day';",
  "rationale": "The question asks for the number of scheduled visits missed last month. A visit is considered missed when its actual_date is NULL (i.e., not completed). We filter visits with actual_date IS NULL and planned_date within the previous calendar month using the interval from DATE('now') - INTERVAL '1 month' to DATE('now') - INTERVAL '1 day'. The COUNT(*) aggregates the total number of such visits, providing a single aggregate result."
}

{
  "sql": "SELECT treatment_arm, COUNT(DISTINCT subject_id) AS enrolled_subjects, COUNT(CASE WHEN severity='Severe' AND serious THEN 1 END) AS serious_events, ROUND(COUNT(CASE WHEN severity='Severe' AND serious THEN 1 END)::DOUBLE / COUNT(DISTINCT subject_id), 2) AS serious_rate FROM subjects s LEFT JOIN adverse_events ae ON s.subject_id = ae.subject_id WHERE s.screening_status IN ('Enrolled','Randomized') GROUP BY treatment_arm;",
  "rationale": "We calculate the serious adverse-event rate for each treatment arm by counting distinct enrolled subjects (enrolled_subjects) and counting serious events (severity='Severe' and serious=TRUE). The rate is the ratio of serious events to enrolled subjects, rounded to two decimals."
}

